198	        if (telephone == null) {
199	            return null;
200	        }
201	        String trimmed = telephone.trim();
202	        boolean hasCountryCode = trimmed.startsWith("+");
203	        // Strip spaces, dashes and brackets; a leading '+' (if any) is left in place.
204	        String stripped = trimmed.replaceAll("[\\s\\-()]", "");
205	        if (hasCountryCode) {
206	            stripped = stripped.substring(1);
207	        }
208	        if (!stripped.matches("\\d+")) {
209	            return null;
210	        }
211	        String digits;
212	        if (hasCountryCode) {
213	            digits = stripped;
214	        } else {
215	            if (stripped.startsWith("0")) {
216	                stripped = stripped.substring(1);
217	            }
218	            digits = "61" + stripped;
219	        }
220	        if (digits.length() < 8 || digits.length() > 15) {
221	            return null;
222	        }
223	        if (!hasValidNationalNumberLength(digits)) {
224	            return null;
225	        }
226	        return "+" + digits;
