245	     * @return {@code true} if the national-number length is valid for the country code
246	     */
247	    private static boolean hasValidNationalNumberLength(String digits) {
248	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
249	            String countryCode = entry.getKey();
250	            if (digits.startsWith(countryCode)) {
251	                return digits.length() - countryCode.length() == entry.getValue();
252	            }
253	        }
254	        return true;
255	    }
