266	    /**
267	     * Normalize an address to its canonical stored form. Leading and trailing whitespace is
268	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
269	     * and common street-type abbreviations are expanded as whole words ({@code ST}->{@code STREET},
270	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). This is the single source of truth for
271	     * how an address is persisted and compared, so inputs that differ only in letter case, spacing
272	     * or abbreviation are treated as the same address. Applied by {@link #setAddress(String)} so
273	     * every persistence path (create and update, mapper or hand-copied) stores the same canonical
274	     * value. The transform is idempotent: a normalized address normalizes to itself.
275	     *
276	     * @param address the raw address, possibly {@code null}
277	     * @return the normalized form, or {@code null} if the input was {@code null}
278	     */
279	    public static String normalizeAddress(String address) {
280	        if (address == null) {
281	            return null;
282	        }
283	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
284	        if (collapsed.isEmpty()) {
285	            return collapsed;
286	        }
287	        String[] tokens = collapsed.split(" ");
288	        StringBuilder normalized = new StringBuilder(collapsed.length());
289	        for (int i = 0; i < tokens.length; i++) {
290	            if (i > 0) {
291	                normalized.append(' ');
292	            }
293	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
294	        }
295	        return normalized.toString();
296	    }
297	
298	    /**
299	     * Normalize a household field (such as last name or address) to its canonical form for
300	     * duplicate-household comparison. Leading and trailing whitespace is trimmed, internal runs
301	     * of whitespace are collapsed to a single space, and the result is lower-cased, so inputs
302	     * that differ only in letter case or spacing are treated as the same value.
303	     *
304	     * @param value the raw field value, possibly {@code null}
305	     * @return the normalized form, or {@code null} if the input was {@code null}
306	     */
307	    public static String normalizeHousehold(String value) {
308	        if (value == null) {
309	            return null;
310	        }
311	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
312	    }
313	
314	    /**
315	     * Compute the stable identifier shared by all owners in the same household, i.e. with the same
316	     * last name (compared case-insensitively with collapsed whitespace, see
317	     * {@link #normalizeHousehold(String)}) and the same normalized address (see
318	     * {@link #normalizeAddress(String)}). The value is deterministic in those two fields, so two
319	     * owners who share a household are assigned the same id. It is formatted {@code 'HH-<HEX12>'}
320	     * where {@code HEX12} is the first twelve upper-cased hex characters of the SHA-256 digest of
321	     * the normalized last name and address.
322	     *
323	     * @param lastName the owner's last name, possibly {@code null}
324	     * @param address the owner's address, possibly {@code null}
325	     * @return the household id, or {@code null} if either field is {@code null}
326	     */
327	    public static String householdId(String lastName, String address) {
328	        String normalizedLastName = normalizeHousehold(lastName);
329	        String normalizedAddress = normalizeAddress(address);
330	        if (normalizedLastName == null || normalizedAddress == null) {
331	            return null;
332	        }
333	        String key = normalizedLastName + "\n" + normalizedAddress;
334	        return "HH-" + sha256Hex(key).substring(0, 12).toUpperCase();
335	    }
336	
337	    /**
338	     * Compute the full lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}. This is the
339	     * shared primitive behind every hash-derived owner value (the household id and the customer code),
340	     * so they all agree on algorithm and encoding.
341	     *
342	     * @param value the string to digest, never {@code null}
343	     * @return the 64-character lower-case hex digest
344	     */
345	    private static String sha256Hex(String value) {
346	        try {
347	            byte[] digest = MessageDigest.getInstance("SHA-256")
348	                .digest(value.getBytes(StandardCharsets.UTF_8));
349	            StringBuilder hex = new StringBuilder(digest.length * 2);
350	            for (byte b : digest) {
351	                hex.append(String.format("%02x", b));
352	            }
353	            return hex.toString();
354	        } catch (NoSuchAlgorithmException e) {
355	            // SHA-256 is a standard algorithm required to be present on every JVM.
356	            throw new IllegalStateException("SHA-256 not available", e);
357	        }
358	    }
359	
360	    /**
361	     * Build an owner's {@code customerCode}, the stable owner identity assigned once when the owner is
362	     * created. It is formatted {@code '<REGION>-<HASH8>'} where:
363	     * <ul>
364	     *   <li>{@code REGION} is the region code derived from the postcode (see
365	     *       {@link #regionForPostcode(String)}), or {@code 'UNKNOWN'} when the postcode is absent or
366	     *       in no known range, and</li>
367	     *   <li>{@code HASH8} is the first eight upper-cased hex characters of the SHA-256 digest of the
368	     *       normalized telephone (see {@link #normalizeTelephone(String)}) concatenated with the last
369	     *       name.</li>
370	     * </ul>
371	     * The value is deterministic in the postcode, telephone and last name (e.g.
372	     * {@code 'NSW-1A2B3C4D'}); it carries no sequence number.
373	     *
374	     * @param postcode the owner's postcode, possibly {@code null}
375	     * @param telephone the owner's raw telephone, possibly {@code null}
376	     * @param lastName the owner's last name, possibly {@code null}
377	     * @return the customer code, or {@code null} if the telephone or last name is {@code null}
378	     */
379	    public static String customerCode(String postcode, String telephone, String lastName) {
380	        if (telephone == null || lastName == null) {
381	            return null;
382	        }
383	        String region = regionForPostcode(postcode);
384	        if (region == null) {
385	            region = "UNKNOWN";
386	        }
387	        String normalizedTelephone = normalizeTelephone(telephone);
388	        String key = (normalizedTelephone == null ? "" : normalizedTelephone) + lastName;
389	        return region + "-" + sha256Hex(key).substring(0, 8).toUpperCase();
390	    }
391	
392	    /**
393	     * Compute an owner's {@code identityKey}, the single derived value through which all
394	     * duplicate detection is now expressed. It consolidates the three formerly separate
395	     * telephone, email and household duplicate checks into one key, formatted as
396	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}:
397	     * <ul>
398	     *   <li>the normalized telephone (see {@link #normalizeTelephone(String)}),</li>
399	     *   <li>the normalized email (see {@link #normalizeEmail(String)}), or the empty string
400	     *       when no email is present, and</li>
401	     *   <li>the household id (see {@link #householdId(String, String)}).</li>
402	     * </ul>
403	     * A {@code null} component is rendered as the empty string. Two owners are the same identity
404	     * only when their <em>whole</em> keys are equal; because the telephone is part of the key, two
405	     * members of the same household with different telephones have different keys.
406	     *
407	     * @param telephone the owner's raw telephone, possibly {@code null}
408	     * @param email the owner's email, possibly {@code null}
409	     * @param lastName the owner's last name, possibly {@code null}
410	     * @param address the owner's address, possibly {@code null}
411	     * @return the identity key, never {@code null}
412	     */
413	    public static String identityKey(String telephone, String email, String lastName, String address) {
414	        String normalizedTelephone = normalizeTelephone(telephone);
415	        String normalizedEmail = normalizeEmail(email);
416	        String household = householdId(lastName, address);
417	        return (normalizedTelephone == null ? "" : normalizedTelephone)
418	            + "|" + (normalizedEmail == null ? "" : normalizedEmail)
419	            + "|" + (household == null ? "" : household);
420	    }
421	
422	    /**
423	     * Build an owner's {@code membershipNumber}, the stable membership identifier derived from the
424	     * owner's own persisted fields. It is formatted {@code '<customerCode>-M<YY>'} where {@code YY}
425	     * is the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}). The
426	     * value is deterministic in those two fields.
427	     *
428	     * @param customerCode the owner's customer code, possibly {@code null}
429	     * @param registrationDate the owner's registration date, possibly {@code null}
430	     * @return the membership number, or {@code null} if either field is {@code null}
431	     */
432	    public static String membershipNumber(String customerCode, LocalDate registrationDate) {
433	        if (customerCode == null || registrationDate == null) {
434	            return null;
435	        }
436	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
437	    }
438	
439	    /**
440	     * Build an owner's {@code membershipLevel}, the derived numeric level assigned on create. The
441	     * value starts at 1, gains 1 when an email is present and gains 1 when {@code namesakeCount} is 0,
442	     * and is capped at 3 (level 4 is reserved for tenure). The value is deterministic in those two
443	     * fields.
444	     *
445	     * @param namesakeCount the owner's namesake count, possibly {@code null}
446	     * @param email the owner's email, possibly {@code null}
447	     * @return the membership level, an integer from 1 to 3
448	     */
449	    public static int membershipLevel(Integer namesakeCount, String email) {
450	        int level = 1;
451	        if (email != null && !email.isEmpty()) {
452	            level++;
453	        }
454	        if (namesakeCount != null && namesakeCount == 0) {
455	            level++;
456	        }
457	        return Math.min(level, 3);
458	    }
459	
460	    /**
461	     * Fixed city-to-region table used by {@link #regionForCity(String)} to resolve a city's region
462	     * for postcode validation, keyed by the exact city name.
463	     */
464	    private static final Map<String, String> CITY_REGION = Map.of(
465	        "Sydney", "NSW",
466	        "Melbourne", "VIC",
467	        "Brisbane", "QLD");
468	
469	    /**
470	     * Derive an owner's {@code locality}, the canonical region for the owner, from the {@code REGION}
471	     * segment of the owner's {@code customerCode} (see {@link #customerCode(String, String, String)}).
472	     * Because the customer code's region is itself derived from the postcode, the locality now shares
473	     * the owner's region-and-hash identity: it is the text before the first {@code '-'} of the customer
474	     * code. When the owner has no customer code the locality is {@code 'UNKNOWN'}.
475	     *
476	     * @param customerCode the owner's customer code, possibly {@code null}
477	     * @return the canonical region string, or {@code 'UNKNOWN'} when no customer code is present
478	     */
479	    public static String locality(String customerCode) {
480	        if (customerCode == null) {
481	            return "UNKNOWN";
482	        }
483	        int dash = customerCode.indexOf('-');
484	        return dash < 0 ? customerCode : customerCode.substring(0, dash);
485	    }
486	
487	    /**
488	     * Resolve the canonical region for a city from the fixed {@link #CITY_REGION} table. A city not
489	     * in the table (including {@code null}) resolves to {@code 'UNKNOWN'}.
490	     *
491	     * @param city the owner's city, possibly {@code null}
492	     * @return the matching region, or {@code 'UNKNOWN'} when the city is not in the table
493	     */
494	    private static String regionForCity(String city) {
495	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
496	    }
497	
498	    /**
499	     * Fixed region-to-postcode-range table used by {@link #isPostcodeValidForCity(String, String)}
500	     * and {@link #regionForPostcode(String)}, keyed by the canonical region. Each entry is the
501	     * inclusive low and high bound of the region's valid 4-digit postcodes
502	     * ({@code NSW} 2000-2099, {@code VIC} 3000-3099, {@code QLD} 4000-4099). A region not in this
503	     * table (including {@code 'UNKNOWN'}) places no range constraint.
504	     */
505	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
506	        "NSW", new int[] {2000, 2099},
507	        "VIC", new int[] {3000, 3099},
508	        "QLD", new int[] {4000, 4099});
509	
510	    /**
511	     * Resolve the canonical region whose postcode range contains the given postcode, using the fixed
512	     * {@link #REGION_POSTCODE_RANGES} table. A {@code null} postcode, one that is not exactly four
513	     * digits, or one that falls in no known range resolves to {@code null}.
514	     *
515	     * @param postcode the owner's postcode, possibly {@code null}
516	     * @return the matching region, or {@code null} when no range contains the postcode
517	     */
518	    private static String regionForPostcode(String postcode) {
519	        if (postcode == null || !postcode.matches("\\d{4}")) {
520	            return null;
521	        }
522	        int value = Integer.parseInt(postcode);
523	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
524	            int[] range = entry.getValue();
525	            if (value >= range[0] && value <= range[1]) {
526	                return entry.getKey();
527	            }
528	        }
529	        return null;
530	    }
531	
532	    /**
533	     * Check whether a postcode is valid for an owner's city. Postcode is optional, so a
534	     * {@code null} or empty postcode is always valid. When present it must be exactly four
535	     * digits, and when the city's region (from the fixed city-to-region table) has a known postcode
536	     * range the value must fall within that inclusive range. A city with no known region accepts
537	     * any four-digit postcode. This is the single source of
538	     * truth for postcode validity, shared by the DTO validation and any persistence path.
539	     *
540	     * @param postcode the owner's postcode, possibly {@code null}
541	     * @param city the owner's city, possibly {@code null}
542	     * @return {@code true} if the postcode is absent or valid for the city, {@code false} otherwise
543	     */
544	    public static boolean isPostcodeValidForCity(String postcode, String city) {
545	        if (postcode == null || postcode.isEmpty()) {
546	            return true;
547	        }
548	        if (!postcode.matches("\\d{4}")) {
549	            return false;
550	        }
551	        int[] range = REGION_POSTCODE_RANGES.get(regionForCity(city));
552	        if (range == null) {
553	            return true;
554	        }
555	        int value = Integer.parseInt(postcode);
556	        return value >= range[0] && value <= range[1];
557	    }
558	
559	    /**
560	     * Compute an owner's {@code checkDigit}, a single Luhn check digit (0-9) over the digits
561	     * contained in the {@code customerCode}. Non-digit characters in the code are ignored. The
562	     * value is deterministic in the customer code and is the standard Luhn check digit: each
563	     * digit is weighted right-to-left, every second digit (starting with the rightmost) is
564	     * doubled with digit sums above nine reduced by nine, and the check digit is the amount that
565	     * brings the weighted sum up to the next multiple of ten.
566	     *
567	     * @param customerCode the owner's customer code, possibly {@code null}
568	     * @return the Luhn check digit from 0 to 9, or {@code null} if the customer code is {@code null}
569	     */
570	    public static Integer checkDigit(String customerCode) {
571	        if (customerCode == null) {
572	            return null;
573	        }
574	        int sum = 0;
575	        boolean dbl = true;
576	        for (int i = customerCode.length() - 1; i >= 0; i--) {
577	            char c = customerCode.charAt(i);
578	            if (c < '0' || c > '9') {
579	                continue;
580	            }
581	            int d = c - '0';
582	            if (dbl) {
583	                d *= 2;
584	                if (d > 9) {
585	                    d -= 9;
586	                }
587	            }
588	            sum += d;
589	            dbl = !dbl;
590	        }
591	        return (10 - (sum % 10)) % 10;
592	    }
593	
594	    /**
595	     * Derive an owner's {@code contactPreference}, the preferred channel for contacting the owner.
596	     * The value is {@code 'EMAIL'} when an email is present and {@code 'PHONE'} otherwise. The value
597	     * is deterministic in the email.
598	     *
599	     * @param email the owner's email, possibly {@code null}
600	     * @return {@code 'EMAIL'} when an email is present, otherwise {@code 'PHONE'}
601	     */
602	    public static String contactPreference(String email) {
603	        return (email != null && !email.isEmpty()) ? "EMAIL" : "PHONE";
604	    }
605	
606	    /**
607	     * Derive an owner's {@code ageBand}, the band the owner's age falls into on the registration
608	     * date. The age in whole years is the number of completed years between {@code birthDate} and
609	     * {@code registrationDate}, and the band is {@code 'MINOR'} when under 18, {@code 'ADULT'} when
610	     * 18 to 64 inclusive, and {@code 'SENIOR'} when 65 or older. The value is deterministic in those
611	     * two fields and is only defined when both are present.
612	     *
613	     * @param birthDate the owner's date of birth, possibly {@code null}
614	     * @param registrationDate the owner's registration date, possibly {@code null}
615	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when either date
616	     *     is {@code null}
617	     */
618	    public static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
619	        if (birthDate == null || registrationDate == null) {
620	            return null;
621	        }
622	        int age = Period.between(birthDate, registrationDate).getYears();
623	        if (age < 18) {
624	            return "MINOR";
625	        }
626	        if (age < 65) {
627	            return "ADULT";
628	        }
629	        return "SENIOR";
630	    }
631	
632	    protected Set<Pet> getPetsInternal() {
633	        if (this.pets == null) {
634	            this.pets = new HashSet<>();
635	        }
636	        return this.pets;
637	    }
638	
639	    protected void setPetsInternal(Set<Pet> pets) {
640	        this.pets = pets;
641	    }
642	
643	    public List<Pet> getPets() {
644	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
645	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
646	        return Collections.unmodifiableList(sortedPets);
647	    }
648	
649	    public void setPets(List<Pet> pets) {
650	        this.pets = new HashSet<>(pets);
651	    }
652	
653	    public void addPet(Pet pet) {
654	        getPetsInternal().add(pet);
655	        pet.setOwner(this);
656	    }
657	
658	    /**
659	     * Return the Pet with the given name, or null if none found for this Owner.
660	     *
661	     * @param name to test
662	     * @return true if pet name is already in use
663	     */
664	    public Pet getPet(String name) {
665	        return getPet(name, false);
666	    }
667	
668	    /**
669	     * Return the Pet with the given name, or null if none found for this Owner.
670	     *
671	     * @param name to test
672	     * @return true if pet name is already in use
673	     */
674	    public Pet getPet(String name, boolean ignoreNew) {
675	        name = name.toLowerCase();
676	        for (Pet pet : getPetsInternal()) {
677	            if (!ignoreNew || !pet.isNew()) {
678	                String compName = pet.getName();
679	                compName = compName.toLowerCase();
680	                if (compName.equals(name)) {
681	                    return pet;
682	                }
683	            }
684	        }
685	        return null;
686	    }
687	
688	    public Pet getPet(Integer petId) {
689	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
690	    }
691	
692	    @Override
693	    public String toString() {
694	        return new ToStringCreator(this)
695	
696	            .append("id", this.getId())
697	            .append("new", this.isNew())
698	            .append("lastName", this.getLastName())
699	            .append("firstName", this.getFirstName())
700	            .append("address", this.address)
701	            .append("city", this.city)
702	            .append("telephone", this.telephone)
703	            .toString();
704	    }
705	}
